INSERT INTO public._dietary_options_v VALUES (1, 1, 'Vegetarian', 'vegetarian', '🥬', '#22c55e', 'No meat, poultry, or fish. May include dairy and eggs depending on the type.', 'published', NULL, NULL, '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', 'published', '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', true, false);
INSERT INTO public._dietary_options_v VALUES (2, 2, 'Vegan', 'vegan', '🌱', '#16a34a', 'No animal products whatsoever — no meat, dairy, eggs, honey, or gelatin.', 'published', NULL, NULL, '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', 'published', '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', true, false);
INSERT INTO public._dietary_options_v VALUES (3, 3, 'Halal', 'halal', '☪️', '#0ea5e9', 'Prepared according to Islamic dietary law. No pork, no alcohol, meat from certified sources.', 'published', NULL, NULL, '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', 'published', '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', true, false);
INSERT INTO public._dietary_options_v VALUES (4, 4, 'Gluten-Free', 'gluten-free', '🌾', '#f59e0b', 'No wheat, barley, rye, or other gluten-containing ingredients.', 'published', NULL, NULL, '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', 'published', '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', true, false);
INSERT INTO public._dietary_options_v VALUES (5, 5, 'Dairy-Free', 'dairy-free', '🥛', '#8b5cf6', 'No milk, cheese, butter, cream, or other dairy products.', 'published', NULL, NULL, '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', 'published', '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', true, false);
INSERT INTO public._dietary_options_v VALUES (6, 6, 'Nut-Free', 'nut-free', '🥜', '#ef4444', 'No peanuts, tree nuts, or nut-derived ingredients. Important for allergy safety.', 'published', NULL, NULL, '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', 'published', '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', true, false);
INSERT INTO public._dietary_options_v VALUES (7, 7, 'Pescatarian', 'pescatarian', '🐟', '#06b6d4', 'No meat or poultry, but fish and seafood are allowed.', 'published', NULL, NULL, '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', 'published', '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', true, false);
INSERT INTO public._dietary_options_v VALUES (9, 9, 'Egg-Free', 'egg-free', '🥚', '#f97316', 'No eggs or egg-derived ingredients.', 'published', NULL, NULL, '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', 'published', '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', true, false);
INSERT INTO public._dietary_options_v VALUES (10, 10, 'Low-Sodium', 'low-sodium', '🧂', '#64748b', 'Reduced salt content. Suitable for those monitoring sodium intake.', 'published', NULL, NULL, '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', 'published', '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', true, false);
INSERT INTO public._dietary_options_v VALUES (11, 11, 'Spicy', 'spicy', '🌶️', '#dc2626', 'Contains chili or hot spices. Can be adjusted for heat tolerance.', 'published', NULL, NULL, '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', 'published', '2026-04-03 13:37:54.003+08', '2026-04-03 13:37:54.003+08', true, false);


