INSERT INTO public._testimonials_v VALUES (6, 6, 'Sarah Johnson', 'Australia', 5, 'The Flavours of Malaysia tour was the highlight of our trip. Our guide was knowledgeable and the food was incredible!', 'Amazing experience!', 'https://se-website-images.s3.nl-ams.scw.cloud/karen_testimonial_faadb8a58e.jpg', NULL, true, false, 'TripAdvisor', 'draft', '2026-04-03 16:09:42.266+08', '2026-04-03 16:09:42.266+08', 'draft', '2026-04-03 16:09:42.27+08', '2026-04-03 16:09:42.27+08', true, false);
