INSERT INTO public._tours_v VALUES (22, 22, 'Night Food Tour around Kuala Lumpur', 'night-food-tour-around-kuala-lumpur', 'Adults Only Adventure', 'Simply Enak''s adults-only adventure reveals hidden speakeasy bars, classic Malaysian food and the forbidden tales of the red-light district.', 'This adults-only adventure reveals hidden speakeasy bars, classic Malaysian food, and the forbidden tales of the red-light district.

