INSERT INTO public._tours_v VALUES (23, 23, 'Night Food Tour around Penang', 'night-food-tour-around-penang', 'Georgetown After Dark', 'Experience Georgetown''s vibrant night food scene. Hawker centres come alive after sunset.', 'Experience Georgetown''s vibrant night food scene. Hawker centres come alive after sunset.

