INSERT INTO public.about_page VALUES (1, 'About Simply Enak | Malaysian Food Tours With Heart', 'Simply Enak has been sharing Malaysian food heritage since 2011. Meet the team, read our story, and see 15 years of press features — from National Geographic to BBC and The Food Ranger.', 'Our Story', 'Born in Malaysia. Raised on street food. Sharing the Malaysia we grew up with, one meal at a time.', 'Meet Pauline, Our Founder', '"<p>Growing up in Malaysia, I spent countless mornings walking through wet markets with my mom. While she haggled for the freshest fish and picked out vegetables, I watched the hawkers craft dishes that had been passed down through generations. The sizzle of char kway teow on a screaming hot wok, the aromatic clouds of curry rising from street stalls, the careful art of folding roti canai. This was my Malaysia.</p><p>When I started bringing friends from other countries around, I realised they were missing this entire world. They''d eat at air-conditioned restaurants with picture menus, never knowing that just two streets away, a grandmother was making laksa the same way her mother taught her 60 years ago.</p><p>Simply Enak started in 2011 because I wanted to share what I experienced as a child. Not the Malaysia you see in guidebooks, but the one I know: the night markets, the family recipes, the vendors who remember your face and your favourite dish. The real Malaysia that tourists walk past every day.</p>"', '[{"label": "Happy Guests", "number": "5,000+"}, {"label": "TripAdvisor Rating", "number": "4.9/5"}, {"label": "Experience", "number": "15 Years"}, {"label": "Group Size", "number": "Max 9"}]', '[{"url": null, "year": "2011", "title": "Simply Enak Founded", "description": "Pauline leads her first food walk through Chow Kit market with a small group of friends. Nobody calls it a tour yet — it''s just lunch.", "logo_domain": "simplyenak.com"}, {"url": null, "year": "2012", "title": "Lonely Planet", "description": "A Lonely Planet researcher joins one of our Petaling Street tours — incognito, as they always are. Simply Enak makes it into the guidebook, one of the most-read travel references in the world.", "logo_domain": "lonelyplanet.com"}, {"url": "https://www.routard.com/guide/kuala_lumpur/4385/activites_.htm", "year": "2013", "title": "Le Guide du Routard", "description": "France''s most-read travel guide lists Simply Enak among Malaysia''s top food experiences — our first major international press recognition.", "logo_domain": "routard.com"}, {"url": null, "year": "2014", "title": "KL Food Trails — City Hall & Time Out KL", "description": "Partnered with Kuala Lumpur City Hall''s Tourism Unit and Time Out KL to map four neighbourhoods that locals eat in every day: Jalan Alor, Kampung Baru, Old KL, and Pudu. The KL Food Trails became a printed map guiding visitors to the stalls and kopitiam that anchor each area — our first step beyond tour guiding into shaping how KL presents its food culture.", "logo_domain": "visitkl.dbkl.gov.my"}, {"url": null, "year": "2015", "title": "National Geographic: Confucius Was a Foodie", "description": "NatGeo''s “Confucius Was a Foodie” series films Season 3 with Pauline guiding the crew through Kuala Lumpur''s Chinese culinary heritage. Our vendor relationships open doors cameras usually don''t get through.", "logo_domain": "nationalgeographic.com"}, {"url": null, "year": "2016", "title": "TLC: Taste Off with Chef Aaron Craze", "description": "British chef Aaron Craze brings TLC''s “Taste Off” to KL. Pauline takes the crew through the hawker stalls and morning markets that make Malaysian food what it is.", "logo_domain": "tlc.com"}, {"url": null, "year": "2017", "title": "TVNZ: Karena & Kasey’s Foreign Flavours", "description": "Karena and Kasey Bird bring their TVNZ cooking series to Penang — Simply Enak shows them the Georgetown food scene that locals eat at every day.", "logo_domain": "tvnz.co.nz"}, {"url": "https://www.timeout.com/penang/things-to-do/simply-enak", "year": "2016", "title": "Time Out Penang", "description": "Time Out names Simply Enak one of Penang''s essential experiences, putting us on the map for food travellers heading north to Georgetown.", "logo_domain": "timeout.com"}, {"url": "https://youtu.be/zZbAAn16JWc", "year": "2016", "title": "BBC Sport", "description": "A BBC Sport team joins our Penang food trail and films the legendary Tiger Char Kway Teow vendor.", "logo_domain": "bbc.co.uk"}, {"url": null, "year": "2018", "title": "Getaway, Channel Nine Australia", "description": "Australian travel show Getaway flies host David Reyne to KL. Pauline takes the crew through Chow Kit wet market and Jalan Alor — the segment airs November 2018 to audiences across Australia.", "logo_domain": "9now.com.au"}, {"url": "https://youtu.be/poY8iDlC6Tk", "year": "2018–2019", "title": "The Food Ranger — 3 Videos", "description": "Trevor James (The Food Ranger, 6M+ subscribers) films three videos with our team across KL''s hawker stalls. Together they''ve reached millions of views.", "logo_domain": "thefoodranger.com"}, {"url": "https://youtu.be/zlqXAnJMREo", "year": "2019–2020", "title": "The Edge TV: Exploring History Through Food", "description": "Malaysian business news channel The Edge TV profiles Simply Enak — Pauline takes the crew through the food stalls that tell KL''s history.", "logo_domain": "theedge.com.my"}, {"url": null, "year": "2020", "title": "COVID: We Stay", "description": "Borders close but we don''t disappear. We keep buying from our vendors, keep the relationships alive, and start running virtual food walks — ready for the day travel opens again.", "logo_domain": null}, {"url": "https://radiomisfits.com/ded286/", "year": "2024", "title": "Destination Eat Drink Podcast", "description": "Pauline joins the Destination Eat Drink podcast to talk about Penang''s food culture — Nyonya cooking, nasi kandar, and why Georgetown stays special.", "logo_domain": "radiomisfits.com"}, {"url": null, "year": "Today", "title": "5,000+ guests and still eating", "description": "Every week, guests from 50+ countries join us at the same stalls we''ve eaten at for 15 years. The guides know the vendors by name. The vendors know us.", "logo_domain": null}]', '[{"title":"Unscripted & Human","description":"We don''t do canned jokes or rehearsed speeches. Our guides are licensed professionals, but they talk to you like friends: sharing real stories, not scripts.","icon":"icon-hands-join"},{"title":"Slow Travel","description":"We walk. We pause. We take the time to appreciate the details: the architecture, the smells, the sounds of the neighbourhood.","icon":"icon-compass"},{"title":"Support Local","description":"We exclusively visit family-run businesses. Your tour fee directly supports the heritage keepers of our food culture.","icon":"icon-heart"}]', '[{"name": "Pauline", "role": "Founder & Lead Guide", "specialty": "15 Years Building Relationships", "description": "Started Simply Enak in 2011 after watching too many tourists miss the real Malaysia. Grew up walking wet markets with her mom, learning which vendors had the freshest fish and the ones worth talking to. Now brings that childhood wonder to every tour."}, {"name": "Danny", "role": "Licensed Guide", "specialty": "Tourism Malaysia Certified", "description": "Licensed guide with deep knowledge of Malaysian food heritage and culture. Passionate about sharing the stories behind every dish and connecting travellers with local communities."}, {"name": "Wei Shen", "role": "Licensed Guide", "specialty": "Tourism Malaysia Certified", "description": "Licensed guide specialising in the cultural history of Malaysian cuisine. Expertly navigates the blend of Malay, Chinese, and Indian influences that define Malaysian food culture."}, {"name": "Ronald", "role": "Licensed Guide", "specialty": "Tourism Malaysia Certified", "description": "Licensed guide with extensive knowledge of local neighbourhoods and vendor relationships. Brings energy and real storytelling to every tour."}, {"name": "Maarten", "role": "Partner", "specialty": "Operations & Growth", "description": "Manages operations and business development, ensuring every aspect of Simply Enak stays true to the same standard: stalls we''d take our own families to."}]', NULL, '2026-04-03 11:19:30.492+08', '2026-04-03 11:19:30.463+08');


