INSERT INTO public.about_page_blocks_philosophy_block VALUES (1, 1, 0, 'philosophySection', 'philosophyBlock', '[{"title":"Unscripted & Human","description":"We don''t do canned jokes or rehearsed speeches. Our guides are licensed professionals, but they talk to you like friends: sharing real stories, not scripts.","icon":"icon-hands-join"},{"title":"Slow Travel","description":"We walk. We pause. We take the time to appreciate the details: the architecture, the smells, the sounds of the neighbourhood.","icon":"icon-compass"},{"title":"Support Local","description":"We exclusively visit family-run businesses. Your tour fee directly supports the heritage keepers of our food culture.","icon":"icon-heart"}]');


