INSERT INTO public.about_page_blocks_team_block_members VALUES (1, 1, 0, 'members', 'Pauline', 'Founder & Lead Guide', '15 Years Building Relationships', 'Started Simply Enak in 2011 after watching too many tourists miss the real Malaysia. Grew up walking wet markets with her mom, learning which vendors had the freshest fish and the ones worth talking to. Now brings that childhood wonder to every tour.', NULL);
INSERT INTO public.about_page_blocks_team_block_members VALUES (2, 1, 1, 'members', 'Danny', 'Licensed Guide', 'Tourism Malaysia Certified', 'Licensed guide with deep knowledge of Malaysian food heritage and culture. Passionate about sharing the stories behind every dish and connecting travellers with local communities.', NULL);
INSERT INTO public.about_page_blocks_team_block_members VALUES (3, 1, 2, 'members', 'Wei Shen', 'Licensed Guide', 'Tourism Malaysia Certified', 'Licensed guide specialising in the cultural history of Malaysian cuisine. Expertly navigates the blend of Malay, Chinese, and Indian influences that define Malaysian food culture.', NULL);
INSERT INTO public.about_page_blocks_team_block_members VALUES (4, 1, 3, 'members', 'Ronald', 'Licensed Guide', 'Tourism Malaysia Certified', 'Licensed guide with extensive knowledge of local neighbourhoods and vendor relationships. Brings energy and real storytelling to every tour.', NULL);
INSERT INTO public.about_page_blocks_team_block_members VALUES (5, 1, 4, 'members', 'Maarten', 'Partner', 'Operations & Growth', 'Manages operations and business development, ensuring every aspect of Simply Enak stays true to the same standard: stalls we''d take our own families to.', NULL);


