INSERT INTO public.about_page_blocks_timeline_block_events VALUES (1, 1, 0, 'events', '2011', 'Simply Enak Founded', 'Pauline leads her first food walk through Chow Kit market with a small group of friends. Nobody calls it a tour yet — it''s just lunch.');
INSERT INTO public.about_page_blocks_timeline_block_events VALUES (2, 1, 1, 'events', '2012', 'Lonely Planet', 'A Lonely Planet researcher joins one of our Petaling Street tours — incognito, as they always are. Simply Enak makes it into the guidebook, one of the most-read travel references in the world.');
INSERT INTO public.about_page_blocks_timeline_block_events VALUES (3, 1, 2, 'events', '2013', 'Le Guide du Routard', 'France''s most-read travel guide lists Simply Enak among Malaysia''s top food experiences — our first major international press recognition.');
INSERT INTO public.about_page_blocks_timeline_block_events VALUES (4, 1, 3, 'events', '2014', 'KL Food Trails — City Hall & Time Out KL', 'Partnered with Kuala Lumpur City Hall''s Tourism Unit and Time Out KL to map four neighbourhoods that locals eat in every day: Jalan Alor, Kampung Baru, Old KL, and Pudu. The KL Food Trails became a printed map guiding visitors to the stalls and kopitiam that anchor each area — our first step beyond tour guiding into shaping how KL presents its food culture.');
INSERT INTO public.about_page_blocks_timeline_block_events VALUES (5, 1, 4, 'events', '2015', 'National Geographic: Confucius Was a Foodie', 'NatGeo''s “Confucius Was a Foodie” series films Season 3 with Pauline guiding the crew through Kuala Lumpur''s Chinese culinary heritage. Our vendor relationships open doors cameras usually don''t get through.');
INSERT INTO public.about_page_blocks_timeline_block_events VALUES (6, 1, 5, 'events', '2016', 'TLC: Taste Off with Chef Aaron Craze', 'British chef Aaron Craze brings TLC''s “Taste Off” to KL. Pauline takes the crew through the hawker stalls and morning markets that make Malaysian food what it is.');
INSERT INTO public.about_page_blocks_timeline_block_events VALUES (7, 1, 6, 'events', '2017', 'TVNZ: Karena & Kasey’s Foreign Flavours', 'Karena and Kasey Bird bring their TVNZ cooking series to Penang — Simply Enak shows them the Georgetown food scene that locals eat at every day.');
INSERT INTO public.about_page_blocks_timeline_block_events VALUES (8, 1, 7, 'events', '2016', 'Time Out Penang', 'Time Out names Simply Enak one of Penang''s essential experiences, putting us on the map for food travellers heading north to Georgetown.');
INSERT INTO public.about_page_blocks_timeline_block_events VALUES (9, 1, 8, 'events', '2016', 'BBC Sport', 'A BBC Sport team joins our Penang food trail and films the legendary Tiger Char Kway Teow vendor.');
INSERT INTO public.about_page_blocks_timeline_block_events VALUES (10, 1, 9, 'events', '2018', 'Getaway, Channel Nine Australia', 'Australian travel show Getaway flies host David Reyne to KL. Pauline takes the crew through Chow Kit wet market and Jalan Alor — the segment airs November 2018 to audiences across Australia.');
INSERT INTO public.about_page_blocks_timeline_block_events VALUES (11, 1, 10, 'events', '2018–2019', 'The Food Ranger — 3 Videos', 'Trevor James (The Food Ranger, 6M+ subscribers) films three videos with our team across KL''s hawker stalls. Together they''ve reached millions of views.');
INSERT INTO public.about_page_blocks_timeline_block_events VALUES (12, 1, 11, 'events', '2019–2020', 'The Edge TV: Exploring History Through Food', 'Malaysian business news channel The Edge TV profiles Simply Enak — Pauline takes the crew through the food stalls that tell KL''s history.');
INSERT INTO public.about_page_blocks_timeline_block_events VALUES (13, 1, 12, 'events', '2020', 'COVID: We Stay', 'Borders close but we don''t disappear. We keep buying from our vendors, keep the relationships alive, and start running virtual food walks — ready for the day travel opens again.');
INSERT INTO public.about_page_blocks_timeline_block_events VALUES (14, 1, 13, 'events', '2024', 'Destination Eat Drink Podcast', 'Pauline joins the Destination Eat Drink podcast to talk about Penang''s food culture — Nyonya cooking, nasi kandar, and why Georgetown stays special.');
INSERT INTO public.about_page_blocks_timeline_block_events VALUES (15, 1, 14, 'events', 'Today', '5,000+ guests and still eating', 'Every week, guests from 50+ countries join us at the same stalls we''ve eaten at for 15 years. The guides know the vendors by name. The vendors know us.');


