INSERT INTO public.dietary_landing_pages_blocks_tips_block VALUES (1, 1, 0, 'tipsSection', 'tipsBlock', '<p><strong>Key phrases:</strong> "Saya vegetarian" (I''m vegetarian), "Tidak makan daging" (Don''t eat meat)</p><p><strong>Look for:</strong> Indian vegetarian restaurants, Chinese Buddhist eateries (often marked with 斋), and dedicated vegetarian stalls</p>');


