INSERT INTO public.home_page_blocks_about_block VALUES (1, 6, 0, 'aboutSection', 'aboutBlock', 'Our Story', 'Born in Malaysia. Raised on Street Food.', 'Sharing the Malaysia we grew up with, one meal at a time.', 'Simply Enak has been sharing Malaysian food heritage since 2011. We started as a small food walk through Kuala Lumpur''s oldest neighborhoods, led by Pauline who grew up exploring wet markets and hawker stalls with her family. Today we host 5,000+ guests a year across KL and Penang — still with the same approach: unscripted, human, and deeply personal.', 'Since 2011', NULL);


