INSERT INTO public.tours VALUES (24, 'Family Food Tour around Kuala Lumpur', 'family-food-tour-around-kuala-lumpur', 'Perfect for Families with Kids', 'Traveling with kids? Simply Enak''s family-friendly tours adjust spice levels, include kid-friendly foods, and move at a comfortable pace.', 'Traveling with kids? Our family-friendly tours adjust spice levels, include kid-friendly foods, and move at a comfortable pace.

Children under 12 are 50% off. We know which vendors have high chairs, where the clean bathrooms are, and how to keep kids engaged.', 285, 'MYR', '3.5 hours', 210, 'Kuala Lumpur', 'Pavilion KL, Kuala Lumpur', 9, 2, true, NULL, NULL, NULL, true, NULL, false, false, false, NULL, 'draft', 'draft', NULL, NULL, NULL, '2026-04-03 11:26:47.487+08', '2026-04-03 11:26:47.487+08', 'published');
INSERT INTO public.tours VALUES (25, 'Family Food Tour around Penang', 'family-food-tour-around-penang', 'Penang''s Best for Families', 'Penang is perfect for families! Simply Enak''s tours are designed with kids in mind - kid-friendly foods, comfortable pace, and fun stories.', 'Penang is perfect for families! Our tours are designed with kids in mind - kid-friendly foods, comfortable pace, and fun stories.

Children under 12 are 50% off. We know the best family-friendly vendors.', 285, 'MYR', '3.5 hours', 210, 'Penang', 'Gurney Drive, Penang', 9, 2, true, NULL, NULL, NULL, true, NULL, false, false, false, NULL, 'draft', 'draft', NULL, NULL, NULL, '2026-04-03 11:26:47.506+08', '2026-04-03 11:26:47.506+08', 'published');
INSERT INTO public.tours VALUES (26, 'Couples Food Tour around Kuala Lumpur', 'couples-food-tour-around-kuala-lumpur', 'Perfect Date Night Experience', 'Looking for something better than dinner and a movie? Food tours are the ultimate couples experience.', 'Looking for something better than dinner and a movie? Food tours are the ultimate couples experience.

You''re not just eating together - you''re discovering together. Trying new things. Sharing reactions. Creating memories.', 289, 'MYR', '4 hours', 240, 'Kuala Lumpur', 'Bukit Bintang, Kuala Lumpur', 9, 2, true, NULL, NULL, NULL, true, NULL, false, false, false, NULL, 'draft', 'draft', NULL, NULL, NULL, '2026-04-03 11:26:47.524+08', '2026-04-03 11:26:47.524+08', 'published');
INSERT INTO public.tours VALUES (27, 'Couples Food Tour around Penang', 'couples-food-tour-around-penang', 'Georgetown Romance & Food', 'Georgetown is perfect for couples! Heritage streets, romantic settings, and amazing food.', 'Georgetown is perfect for couples! Heritage streets, romantic settings, and amazing food.

We''ll guide you through atmospheric stops perfect for couples - sunset views, heritage shophouses, and shareable dishes.', 359, 'MYR', '4 hours', 240, 'Penang', 'Georgetown, Penang', 9, 2, true, NULL, NULL, NULL, true, NULL, false, false, false, NULL, 'draft', 'draft', NULL, NULL, NULL, '2026-04-03 11:26:47.539+08', '2026-04-03 11:26:47.539+08', 'published');
INSERT INTO public.tours VALUES (28, 'Foodie Tour around Kuala Lumpur', 'foodie-tour-around-kuala-lumpur', 'For Serious Food Lovers', 'You''re not a tourist who eats. You''re a traveler who eats strategically. This tour is for you.', 'You''re not a tourist who eats. You''re a traveler who eats strategically. You research restaurants before booking flights.

We go deeper: chef interviews, recipe discussions, technique demonstrations. This isn''t a tour. It''s a masterclass.', 299, 'MYR', '4 hours', 240, 'Kuala Lumpur', 'Jalan Alor, Kuala Lumpur', 9, 2, true, NULL, NULL, NULL, true, NULL, false, false, false, NULL, 'draft', 'draft', NULL, NULL, NULL, '2026-04-03 11:26:47.557+08', '2026-04-03 11:26:47.557+08', 'published');
INSERT INTO public.tours VALUES (29, 'Foodie Tour around Penang', 'foodie-tour-around-penang', 'Penang''s Best for Food Lovers', 'Penang is the food capital of Malaysia - and this tour is for serious food lovers.', 'Penang is the food capital of Malaysia - and this tour is for serious food lovers.

We''ll take you beyond the tourist spots to where serious foodies eat. Meet vendors who''ve been perfecting recipes for 40+ years.', 299, 'MYR', '4 hours', 240, 'Penang', 'New Lane Hawker Centre, Penang', 9, 2, true, NULL, NULL, NULL, true, NULL, false, false, false, NULL, 'draft', 'draft', NULL, NULL, NULL, '2026-04-03 11:26:47.577+08', '2026-04-03 11:26:47.577+08', 'published');
INSERT INTO public.tours VALUES (30, 'Best Food Tour in Chow Kit Market', 'food-tour-around-chow-kit-market', 'The Best Chow Kit Market Experience', 'Looking for the best food tour in Chow Kit? You''ve found it. Simply Enak has been guiding visitors through this historic market for 14 years. Discover exotic fruits, aromatic spices, and local delicacies with KL''s best-rated market tour.', 'Discover Chow Kit Market, KL''s largest wet market - a sprawling maze where locals have shopped for 100+ years. No souvenir shops. No tourist traps. Just real KL.

We''ll guide you through the maze, introducing you to vendors who''ve been here for generations. Taste exotic fruits, aromatic spices, and local delicacies you''ve never seen.', 289, 'MYR', '3.5 hours', 210, 'Kuala Lumpur', 'Chow Kit Market, Kuala Lumpur', 9, 2, true, NULL, NULL, NULL, true, NULL, false, false, false, NULL, 'draft', 'draft', NULL, NULL, NULL, '2026-04-03 11:26:47.595+08', '2026-04-03 11:26:47.595+08', 'published');
INSERT INTO public.tours VALUES (31, 'Best Food Tour in Chinatown Petaling Street', 'food-tour-around-chinatown-petaling-street', 'The Best Chinatown KL Experience', 'Looking for the best food tour in Chinatown KL? You''ve found it. Simply Enak has been guiding visitors through Petaling Street for 14 years. Discover temples, historic lanes, and amazing food with KL''s best-rated Chinatown tour.', 'Brand new to Malaysia? This is everything you need to know!

We''ll guide you through major temples and historic lanes in Chinatown with amazing food. Perfect introduction to Malaysian culture and heritage.

Every dish and vendor has a story.', 289, 'MYR', '4 hours', 240, 'Kuala Lumpur', 'Petaling Street, Chinatown, Kuala Lumpur', 9, 2, true, NULL, NULL, NULL, true, NULL, false, false, false, NULL, 'draft', 'draft', NULL, NULL, NULL, '2026-04-03 11:26:47.611+08', '2026-04-03 11:26:47.61+08', 'published');
INSERT INTO public.tours VALUES (32, 'Best Food Tour in Brickfields Little India', 'food-tour-around-brickfields-little-india', 'The Best Little India KL Experience', 'Looking for the best food tour in Little India KL? You''ve found it. Simply Enak has been guiding visitors through Brickfields for 14 years. Discover authentic Indian vegetarian restaurants and banana leaf rice with KL''s best-rated Little India tour.', 'Brickfields has one of Asia''s strongest vegetarian scenes, thanks to 140 years of Indian vegetarian tradition.

We''ll guide you through authentic Indian vegetarian restaurants, banana leaf rice houses, and modern Indian cafes. Every vendor is verified for dietary needs.', 289, 'MYR', '4 hours', 240, 'Kuala Lumpur', 'Brickfields, Kuala Lumpur', 9, 2, true, NULL, NULL, NULL, true, NULL, false, false, false, NULL, 'draft', 'draft', NULL, NULL, NULL, '2026-04-03 11:26:47.628+08', '2026-04-03 11:26:47.628+08', 'published');
INSERT INTO public.tours VALUES (33, 'Best Food Tour in Kampung Baru Malay Village', 'food-tour-around-kampung-baru-malay-village', 'The Best Malay Village Experience KL', 'Looking for the best food tour in Kampung Baru? You''ve found it. Simply Enak has been guiding visitors through this traditional Malay village for 14 years. Discover authentic Malay cuisine with KL''s best-rated village tour.', 'Kampung Baru is a traditional Malay village in the heart of KL - a wooden house enclave surrounded by skyscrapers.

We''ll guide you through authentic Malay cuisine, from nasi lemak to rendang, all prepared using traditional recipes passed down through generations.', 289, 'MYR', '4 hours', 240, 'Kuala Lumpur', 'Kampung Baru, Kuala Lumpur', 9, 2, true, NULL, NULL, NULL, true, NULL, false, false, false, NULL, 'draft', 'draft', NULL, NULL, NULL, '2026-04-03 11:26:47.645+08', '2026-04-03 11:26:47.645+08', 'published');
INSERT INTO public.tours VALUES (34, 'Best Food Tour in Chowrasta Market Penang', 'food-tour-around-chowrasta-market-penang', 'The Best Chowrasta Market Experience', 'Looking for the best food tour in Chowrasta Market? You''ve found it. Simply Enak has been guiding visitors through Penang''s historic market for 14 years. Watch popiah being made, taste Asam Laksa, and discover why we''re Penang''s best-rated market tour.', 'What makes Penang the "food capital" of Malaysia? Start at Chowrasta Market, the heart of Penang food culture.

We''ll dare you to try kopitiam "Ngor Ka Sai", signature nutmeg pickles and dodol. You''ll watch a master handcraft popiah skin, and taste legendary Asam Laksa.', 289, 'MYR', '3.5 hours', 210, 'Penang', 'Chowrasta Market, Penang', 9, 2, true, NULL, NULL, NULL, true, NULL, false, false, false, NULL, 'draft', 'draft', NULL, NULL, NULL, '2026-04-03 11:26:47.664+08', '2026-04-03 11:26:47.664+08', 'published');
INSERT INTO public.tours VALUES (35, 'Best Food Tour in Georgetown Penang', 'food-tour-around-georgetown-heritage', 'The Best Georgetown Heritage Experience', 'Looking for the best food tour in Georgetown Penang? You''ve found it. Simply Enak has been guiding visitors through UNESCO Georgetown for 14 years. Discover Peranakan culture, temples, street art, and amazing food with Penang''s best-rated heritage tour.', 'Explore Georgetown UNESCO heritage streets while tasting Peranakan culture through colourful kuey and legendary dishes.

We''ll share Peranakan culture, explore temples and street art, and you''ll leave with the history and culture behind Penang''s most famous flavours.', 359, 'MYR', '4 hours', 240, 'Penang', 'Georgetown, Penang', 9, 2, true, NULL, NULL, NULL, true, NULL, false, false, false, NULL, 'draft', 'draft', NULL, NULL, NULL, '2026-04-03 11:26:47.678+08', '2026-04-03 11:26:47.678+08', 'published');
INSERT INTO public.tours VALUES (36, 'Best Food Tour in Gurney Drive Penang', 'food-tour-around-gurney-drive', 'The Best Gurney Drive Hawker Experience', 'Looking for the best food tour in Gurney Drive? You''ve found it. Simply Enak has been guiding visitors through Penang''s famous hawker centre for 14 years. Taste sizzling satay, char kway teow, and waterfront dining with Penang''s best-rated hawker tour.', 'Gurney Drive is Penang''s most famous hawker centre - a waterfront food paradise.

We''ll guide you through the best stalls, taste sizzling satay, char kway teow, and experience the vibrant hawker culture that makes Penang famous.', 285, 'MYR', '3.5 hours', 210, 'Penang', 'Gurney Drive, Penang', 9, 2, true, NULL, NULL, NULL, true, NULL, false, false, false, NULL, 'draft', 'draft', NULL, NULL, NULL, '2026-04-03 11:26:47.694+08', '2026-04-03 11:26:47.694+08', 'published');
INSERT INTO public.tours VALUES (37, 'Best Food Tour in Little India Penang', 'food-tour-around-little-india-lebuh-queen', 'The Best Little India Lebuh Queen Experience', 'Looking for the best food tour in Little India Penang? You''ve found it. Simply Enak has been guiding visitors through Lebuh Queen for 14 years. Discover authentic Indian restaurants, banana leaf rice, and spice shops with Penang''s best-rated Little India tour.', 'Penang''s Little India on Lebuh Queen is a sensory explosion of spices, textiles, and authentic Indian food.

We''ll guide you through authentic Indian restaurants, banana leaf rice houses, and sweet shops. Every vendor is verified for dietary needs.', 285, 'MYR', '3.5 hours', 210, 'Penang', 'Lebuh Queen, Little India, Penang', 9, 2, true, NULL, NULL, NULL, true, NULL, false, false, false, NULL, 'draft', 'draft', NULL, NULL, NULL, '2026-04-03 11:26:47.71+08', '2026-04-03 11:26:47.71+08', 'published');


