INSERT INTO public.travel_type_landing_pages VALUES (1, 'Family-Friendly', 'family', 'published', 'family_restroom', '#3B82F6', 'Family Tours Malaysia', 'Kids Welcome.', 'Most tours not for families. Ours are.', NULL, 'Why Families', 'Kid portions. Bathroom breaks.', 'Slower. 6-8 kid stops.', NULL, '"[\"Flavours MY\",\"KL Street\"]"', '"[{\"icon\":\"child_friendly\",\"title\":\"Kid Menus\"}]"', 'Family Food Tours Malaysia: Kid-Friendly | Simply Enak', 'Family-friendly food tours in KL and Penang. Kid-sized portions, bathroom breaks, slower pace. Children welcome on all tours. From RM 285.', NULL, NULL, '2026-04-03 11:27:33.619+08', '2026-04-03 11:27:33.619+08');
INSERT INTO public.travel_type_landing_pages VALUES (2, 'Couples', 'couples', 'published', 'favorite', '#EC4899', 'Couples Tours Malaysia', 'Date Night Different.', 'Skip the dinner-and-movie routine. Share 10+ dishes, discover new flavors together, create memories over char kway teow.', NULL, 'Why Couples Love Our Tours', 'Small groups (max 9), intimate vendor conversations, shared discoveries. Perfect for date night or anniversary trips.', '4-5 hours, 8-10 food stops, romantic neighborhoods (Chinatown, Georgetown), evening tours available.', 'Book evening tours for cooler weather. Private tours available for just the two of you.', '"[\"Eat Drink GT\"]"', '"[{\"icon\":\"restaurant\",\"title\":\"Shareable\"}]"', 'Couples Food Tours Malaysia: Date Night | Simply Enak', 'Romantic food tours for couples in KL and Penang. Small groups, intimate settings, shared discoveries. Perfect date night. From RM 285.', NULL, NULL, '2026-04-03 11:27:33.625+08', '2026-04-03 11:27:33.625+08');
INSERT INTO public.travel_type_landing_pages VALUES (3, 'Foodie', 'foodie', 'published', 'ramen_dining', '#F59E0B', 'Foodie Tours Malaysia', 'For Serious Food Lovers.', 'For travelers who read menus for fun. Go beyond tourist dishes — discover hawker culture, generational recipes, food that tells a story.', NULL, 'Why Foodies Choose Us', '14 years of food expertise. We know which stalls have been family-run for 40+ years, which recipes haven''t changed, which vendors will share their stories.', '10+ tastings, 8-10 stalls, cultural context for every dish, vendor introductions, recipe histories.', 'Come hungry. Ask questions — our founders (Pauline & Maarten) love talking food. Request the ''chef''s tour'' for extra tastings.', '"[\"All tours\"]"', '"[{\"icon\":\"chef_hat\",\"title\":\"Chef Access\"}]"', 'Foodie Tours Malaysia: For Serious Eaters | Simply Enak', 'Food lover tours in KL and Penang. 10+ tastings, generational vendors, recipe histories. For serious foodies. From RM 285.', NULL, NULL, '2026-04-03 11:27:33.631+08', '2026-04-03 11:27:33.631+08');
INSERT INTO public.travel_type_landing_pages VALUES (4, 'Solo Traveler', 'solo', 'published', 'person', '#8B5CF6', 'Solo Tours Malaysia', 'You Will Not Eat Alone.', 'Traveling alone doesn''t mean eating alone. Join small groups, make friends over food, discover KL with fellow travelers.', NULL, 'Why Solo Travelers Love Us', 'Small groups (max 9) mean you''ll actually meet people. No awkward single supplements. Just good food, good company, good stories.', 'Mixed groups of travelers and locals, conversation-friendly pace, photo opportunities, new friends guaranteed.', 'Join-in tours are perfect for solo travelers. Book evening tours to meet more people. We''ll help with photos!', '"[\"All tours\"]"', '"[{\"icon\":\"groups\",\"title\":\"Small Groups\"}]"', 'Solo Traveler Food Tours Malaysia | Join Groups | Simply Enak', 'Solo food tours in KL and Penang. Join small groups, make friends, eat amazing food. No single supplement. From RM 285.', NULL, NULL, '2026-04-03 11:27:33.637+08', '2026-04-03 11:27:33.637+08');


